SELECT CASE WHEN budget >= 3059000 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_tier, location, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, SIZE(COLLECT_SET(location)) AS num_locations, SUM(CASE WHEN location = 'Tokyo' THEN budget ELSE 0 END) AS tokyo_budget FROM departments GROUP BY GROUPING SETS ((CASE WHEN budget >= 3059000 THEN 'PREMIUM' ELSE 'STANDARD' END, location), (CASE WHEN budget >= 3059000 THEN 'PREMIUM' ELSE 'STANDARD' END)) ORDER BY budget_tier DESC NULLS FIRST
